{
  "schemaVersion": 1,
  "name": "crashtest-site",
  "description": "crashtest attacks the site it actually ships: headers claim audit, CSP canary bypass attempts, HTML secret leakage, sitemap truth audit, manifest icon checks, robots.txt self-sabotage, version-function robustness + cache poisoning + shape-flap burst, taxonomy probes (abuse never 5xx, sad-path bodies stay impersonal), + session probes (a cookie-less site must mint zero cookies; a forged cookie is never adopted or reflected), an authz probe (nothing ships advertising a privileged surface; role-claim bodies flip nothing), + a proto-hygiene battery (HEAD mirrors GET on every asset route; bare-shape query chaos never takes an asset serve down), a recursion depth sweep (deep-nested bodies and backtracking-shaped strings never take an asset serve down), a multipart hardening probe (hostile filenames and polyglot carriers never reflect or fault), + an asset-parity race burst (12 concurrent GETs of the same asset come back byte-identical). Self-contained: bundles its own attacks and registry double.",
  "version": "0.2.0",
  "entry": "attacks.js",
  "env": {
    "routes": ["version", "site-headers", "site-html", "site-manifest", "site-sitemap", "site-robotstxt"]
  }
}

{
  "schemaVersion": 1,
  "name": "next-middleware-shapes",
